# base_agent.py
# agents/base_agent.py
"""
Base class for all AI agents.
Every agent has access to Strategy DNA through the query engine.
"""

from abc import ABC, abstractmethod
from typing import Dict, List, Optional, Any
from dataclasses import dataclass, field
from datetime import datetime
from strategy_engine.strategy_dna.query_engine import StrategyQueryEngine
from strategy_engine.strategy_dna.loader import StrategyDNALoader
import logging

logger = logging.getLogger(__name__)


@dataclass
class AgentInsight:
    """A single insight generated by an agent."""
    agent_name: str
    insight_type: str           # execution, behavioral, performance, risk, coaching
    severity: str               # info, warning, critical, positive
    title: str
    message: str
    data: Dict = field(default_factory=dict)
    trade_ids: List[str] = field(default_factory=list)
    strategy_name: Optional[str] = None
    timestamp: datetime = field(default_factory=datetime.now)
    actionable: bool = True
    action_suggestion: Optional[str] = None


class BaseAgent(ABC):
    """
    Abstract base agent that all intelligence agents inherit from.
    Provides access to strategy DNA and shared utilities.
    """

    def __init__(
        self,
        name: str,
        strategy_query: Optional[StrategyQueryEngine] = None,
        db=None,
    ):
        self.name = name
        self.strategy_query = strategy_query
        self.db = db

    @abstractmethod
    def analyze(self, context: Dict) -> List[AgentInsight]:
        """Run analysis and generate insights."""
        pass

    def get_strategy_context(self, strategy_name: str) -> str:
        """Get full strategy DNA context for reasoning."""
        return self.strategy_query.get_agent_context(strategy_name)

    def get_regime_guidance(self, strategy_name: str, regime: str) -> str:
        """Get regime-specific guidance."""
        return self.strategy_query.get_regime_context_for_agent(strategy_name, regime)